// Generated by tools/animations/export-original-clips.ts from the original fighter models; regenerate instead of editing.
// The original-model clip pool: one model per original sequence, so a clip plays by setting its time.
// Each fighter's clips are in its own file, which a re-export rewrites alone; this index changes only when a fighter is added.
import type { FighterOriginalClip } from "./fighterOriginalClip";
import * as illidan from "./illidan";
import * as blademaster from "./blademaster";
import * as mountainKing from "./mountain-king";
import * as lich from "./lich";
import * as dreadlord from "./dreadlord";
import * as pitLord from "./pit-lord";
import * as beastmaster from "./beastmaster";
import * as lichKing from "./lich-king";
import * as jainaProudmoore from "./jaina-proudmoore";
import * as sylvanasWindrunner from "./sylvanas-windrunner";
import * as chenStormstout from "./chen-stormstout";
import * as peon from "./peon";
import * as murloc from "./murloc";
import * as gromHellscream from "./grom-hellscream";
import * as malfurionStormrage from "./malfurion-stormrage";
import * as medivh from "./medivh";
import * as thrall from "./thrall";
import * as kaelthasSunstrider from "./kael'thas-sunstrider";
import * as warden from "./warden";
import * as anubarak from "./anub'arak";
import * as rifleman from "./rifleman";
import * as cairneBloodhoof from "./cairne-bloodhoof";
import * as uther from "./uther";
import * as ladyVashj from "./lady-vashj";
import * as goblinTinker from "./goblin-tinker";
import * as shadowHunter from "./shadow-hunter";
import * as archimonde from "./archimonde";

/** The light model's animation while its fighter is shown, and while hidden. */
export const ORIGINAL_LIGHT_ACTIVE_ANIMATION = "Stand";
export const ORIGINAL_LIGHT_INACTIVE_ANIMATION = "Death";
export const ORIGINAL_LIGHT_GATE_SECONDS = 0.5;

interface FighterClips {
  readonly clips: readonly FighterOriginalClip[];
  readonly names: ReadonlyMap<string, number>;
  readonly light: string | undefined;
}

/** Each character's clips by original sequence index, sequence names and light model. */
const FIGHTERS: Readonly<Record<number, FighterClips>> = {
  2: illidan,
  3: blademaster,
  4: mountainKing,
  6: lich,
  8: dreadlord,
  10: pitLord,
  11: beastmaster,
  12: lichKing,
  14: jainaProudmoore,
  15: sylvanasWindrunner,
  17: chenStormstout,
  18: peon,
  21: murloc,
  22: gromHellscream,
  24: malfurionStormrage,
  25: medivh,
  13: thrall,
  20: kaelthasSunstrider,
  5: warden,
  23: anubarak,
  1: rifleman,
  16: cairneBloodhoof,
  27: uther,
  28: ladyVashj,
  19: goblinTinker,
  9: shadowHunter,
  29: archimonde,
};

/** Clips 0 to count - 1 exist for this character. */
export function originalClipCount(character: number): number {
  return FIGHTERS[character]?.clips.length ?? 0;
}

/** The light model that accompanies this character's clips, if it has one. */
export function originalLightPath(character: number): string | undefined {
  return FIGHTERS[character]?.light;
}

/** The clip for an original sequence index; times are seconds within the clip. */
export function originalClip(character: number, sequenceIndex: number): FighterOriginalClip | undefined {
  return FIGHTERS[character]?.clips[sequenceIndex];
}

/** The sequence index of an original sequence name, such as "walk alternate". */
export function originalClipNamed(character: number, name: string): number | undefined {
  return FIGHTERS[character]?.names.get(name);
}

/** Every original sequence name with its index. */
export function originalClipNames(character: number): ReadonlyMap<string, number> {
  return FIGHTERS[character]?.names ?? new Map();
}
